style.css:
/* Change the background color of the page */
body {
    background-color: #ffe6f2 !important; /* Light pink */
    color: #333 !important; /* Keep text readable */
}

/* Links: Update their color */
a {
    color: #ff69b4 !important; /* Hot pink for links */
    text-decoration: none !important;
}

a:hover {
    color: #ff85c0 !important; /* Softer pink when hovering over links */
}

/* Buttons: Apply pink color scheme */
button, input[type="button"], input[type="submit"] {
    background-color: #ff69b4 !important; /* Hot pink */
    color: white !important;
    border: none;
}

button:hover, input[type="button"]:hover, input[type="submit"]:hover {
    background-color: #ff85c0 !important; /* Softer pink on hover */
}

/* Selected text highlight */
::selection {
    background: #ff69b4 !important; /* Hot pink selection */
    color: white !important;
}

/* Profile panels and sections (example) */
div {
    background-color: #ffebf5 !important; /* Light pink background for divs */
    border-color: #ff69b4 !important; /* Hot pink borders for div elements */
}
